package ro.leo.visual;
import android.content.*;import android.os.Bundle;import android.net.Uri;import android.provider.Settings;import android.util.*;import android.graphics.BitmapFactory;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
import android.util.Base64;

/** Versioned, checksummed local JSON; fixed destinations, preflight validation and rollback journal. */
final class BackupEngine {
 static final int MAX=8*1024*1024;static final String[] GROUPS={"appearance","dialer-favorites","speed-dial","notes-draft","files-ui","music-library","android-apps","home-menu","clock"};
 static final String[] SECURE={InputSettingsActivity.MODE,InputSettingsActivity.DELAY,"leo_keypad_learn_choices"};
 static final Uri IME=Uri.parse("content://ro.leo.keypad.backup");
 static boolean allowed(String group,String key,String type){if(group.equals("music-library"))return key.equals("favorites")&&type.equals("set");if(group.equals("android-apps"))return (key.equals("favorites")||key.equals("hidden"))&&type.equals("set");if(group.equals("home-menu"))return (key.equals("favorites")||key.equals("recent"))&&type.equals("string");if(group.equals("clock"))return key.equals("zones")?type.equals("string"):key.equals("snooze")&&type.equals("int");if(group.equals("appearance")){if(Arrays.asList("warm","list","large-text","home-compact","home-sims","home-unread","home-dbm","home-weather","home-alarm","home-music","lock-wallpaper","lock-info","lock-media").contains(key))return type.equals("boolean");if((key.startsWith("app-theme-")&&java.util.Arrays.asList(StyleSettingsActivity.APPS).contains(key.substring(10)))||key.equals("accent")||key.equals("theme")||key.equals("lock-preview")||key.matches("shortcut[0-3]"))return type.equals("int");return key.equals("app-order")&&type.equals("string");}if(group.equals("dialer-favorites"))return key.matches("(name|number)[0-2]")&&type.equals("string");if(group.equals("speed-dial"))return key.matches("(name|number)[2-9]")&&type.equals("string");if(group.equals("notes-draft"))return key.equals("editing")?type.equals("boolean"):(key.equals("body")||key.equals("id"))&&type.equals("string");return group.equals("files-ui")&&key.equals("sort")&&type.equals("int");}
 static String type(Object v){return v instanceof java.util.Set||v instanceof JSONArray?"set":v instanceof Boolean?"boolean":v instanceof Integer?"int":v instanceof String?"string":"unsupported";}
 static byte[] bytes(File f,int max)throws IOException{try(InputStream in=new FileInputStream(f);ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(b.size()+n>max)throw new IOException("Fișier peste limită");b.write(buf,0,n);}return b.toByteArray();}}
 static boolean atomicExists(File f){return f.exists()||new File(f.getPath()+".bak").exists();}
 static byte[] atomicBytes(File f,int max)throws IOException{try(InputStream in=new AtomicFile(f).openRead();ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1){if(b.size()+n>max)throw new IOException("Fișier peste limită");b.write(buf,0,n);}return b.toByteArray();}}
 static String hash(byte[] bytes)throws Exception{StringBuilder s=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(bytes))s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 static Bundle dictionary(Context c,String method,JSONObject data)throws Exception{Bundle b=new Bundle();if(data!=null){b.putString("words",data.getString("words"));b.putInt("mode",data.getInt("mode"));}Bundle result=c.getContentResolver().call(IME,method,null,b);if(result==null)throw new IOException("Actualizează tastatura Leo");return result;}
 static JSONObject snapshot(Context c)throws Exception{JSONObject data=new JSONObject(),groups=new JSONObject();for(String group:GROUPS){JSONObject values=new JSONObject();for(Map.Entry<String,?> e:c.getSharedPreferences(group,0).getAll().entrySet()){String t=type(e.getValue());if(allowed(group,e.getKey(),t))values.put(e.getKey(),new JSONObject().put("type",t).put("value",e.getValue() instanceof Set?new JSONArray((Set)e.getValue()):e.getValue()));}groups.put(group,values);}data.put("preferences",groups);File notes=new File(c.getFilesDir(),"notes.json");data.put("notes",atomicExists(notes)?new JSONArray(new String(atomicBytes(notes,4*1024*1024),StandardCharsets.UTF_8)):JSONObject.NULL);File wallpaper=Appearance.wallpaper(c);data.put("wallpaper",atomicExists(wallpaper)?Base64.encodeToString(atomicBytes(wallpaper,2*1024*1024),Base64.NO_WRAP):JSONObject.NULL);Bundle words=dictionary(c,"snapshot",null);data.put("dictionary",new JSONObject().put("words",words.getString("words","")).put("mode",words.getInt("mode",0)));JSONObject secure=new JSONObject();for(String key:SECURE){String value=Settings.Secure.getString(c.getContentResolver(),key);secure.put(key,value==null?JSONObject.NULL:value);}data.put("keyboard",secure);data.put("calendar",CalendarArchive.snapshot(c));return data;}
 static void validate(Context c,JSONObject d)throws Exception{for(String key:new String[]{"preferences","notes","wallpaper","dictionary","keyboard"})if(!d.has(key))throw new IOException("Backup incomplet");JSONObject p=d.getJSONObject("preferences");for(Iterator<String> it=p.keys();it.hasNext();)if(!Arrays.asList(GROUPS).contains(it.next()))throw new IOException("Grup incompatibil");for(String group:new String[]{"appearance","dialer-favorites","speed-dial","notes-draft","files-ui"})if(!p.has(group))throw new IOException("Grup absent");for(String group:GROUPS){if(!p.has(group))continue;JSONObject g=p.getJSONObject(group);if(g.length()>100)throw new IOException("Prea multe preferințe");for(Iterator<String> i=g.keys();i.hasNext();){String key=i.next();JSONObject row=g.getJSONObject(key);String t=row.getString("type");Object value=row.get("value");if(!allowed(group,key,t)||!type(value).equals(t))throw new IOException("Preferință invalidă");if(t.equals("set")){JSONArray set=row.getJSONArray("value");if(set.length()>500)throw new IOException("Maximum 500 favorite");for(int at=0;at<set.length();at++)if(!(set.get(at) instanceof String)||set.getString(at).length()>2048)throw new IOException("Referință invalidă");}if(group.equals("clock")&&key.equals("snooze")&&!Arrays.asList(5,10,15).contains(row.getInt("value")))throw new IOException("Amânare invalidă");if(value instanceof String&&((String)value).length()>32768)throw new IOException("Text peste limită");if(t.equals("int")){int n=(Integer)value;if(((key.equals("theme")||key.startsWith("app-theme-"))&&(n<0||n>=Appearance.THEMES.length))||(key.equals("accent")&&(n< -1||n>=Appearance.ACCENTS.length))||(key.matches("shortcut[0-3]")&&(n<0||n>=AppCatalog.NAMES.length))||(key.equals("sort")&&(n<0||n>2))||(key.equals("lock-preview")&&(n<0||n>2)))throw new IOException("Valoare invalidă");}}}
  if(d.has("calendar"))CalendarArchive.validate(d.getJSONArray("calendar"));
  if(!d.isNull("notes")){JSONArray notes=d.getJSONArray("notes");if(notes.length()>100)throw new IOException("Maximum 100 de notițe");HashSet<String> ids=new HashSet<String>();for(int i=0;i<notes.length();i++){JSONObject n=notes.getJSONObject(i);String id=n.getString("id");if(n.has("pinned")&&!(n.get("pinned") instanceof Boolean))throw new IOException("Fixare invalidă");if(id.isEmpty()||id.length()>128||!ids.add(id)||n.getString("body").length()>8192)throw new IOException("Notiță invalidă");}}
  if(!d.isNull("wallpaper")){byte[] image=Base64.decode(d.getString("wallpaper"),Base64.DEFAULT);if(image.length>2*1024*1024)throw new IOException("Fundal prea mare");BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(image,0,image.length,o);if(o.outWidth<1||o.outHeight<1||o.outWidth>2048||o.outHeight>2048)throw new IOException("Fundal invalid");}
  JSONObject keys=d.getJSONObject("keyboard");if(keys.length()!=3)throw new IOException("Tastatură incompatibilă");for(String key:SECURE)if(!keys.has(key))throw new IOException("Setare tastatură absentă");for(int i=0;i<SECURE.length;i++)if(!keys.isNull(SECURE[i])){int n=Integer.parseInt(keys.getString(SECURE[i]));if((i==0&&(n< -1||n>4))||(i==1&&(n<300||n>3000))||(i==2&&(n<0||n>1)))throw new IOException("Setare tastatură invalidă");}dictionary(c,"validate",d.getJSONObject("dictionary"));
 }
 static byte[] archive(JSONObject data)throws Exception{String payload=data.toString();byte[] raw=payload.getBytes(StandardCharsets.UTF_8);byte[] out=new JSONObject().put("format","leo-backup").put("version",2).put("created",System.currentTimeMillis()).put("sha256",hash(raw)).put("payload",payload).toString().getBytes(StandardCharsets.UTF_8);if(out.length>MAX)throw new IOException("Backup peste 8 MiB");return out;}
 static JSONObject read(Context c,File file)throws Exception{JSONObject a=new JSONObject(new String(atomicBytes(file,MAX),StandardCharsets.UTF_8));if(!"leo-backup".equals(a.getString("format"))||(a.getInt("version")!=1&&a.getInt("version")!=2))throw new IOException("Format necunoscut");String payload=a.getString("payload");if(!hash(payload.getBytes(StandardCharsets.UTF_8)).equals(a.getString("sha256")))throw new IOException("Backup deteriorat");JSONObject data=new JSONObject(payload);validate(c,data);return data;}
 static void write(File f,byte[] bytes)throws IOException{AtomicFile a=new AtomicFile(f);FileOutputStream out=null;try{out=a.startWrite();out.write(bytes);a.finishWrite(out);}catch(IOException e){if(out!=null)a.failWrite(out);throw e;}}
 static File export(Context c,File folder)throws Exception{if(!folder.isDirectory()&&!folder.mkdirs())throw new IOException("Stocare indisponibilă");JSONObject data=snapshot(c);validate(c,data);File f=new File(folder,"leo-"+new java.text.SimpleDateFormat("yyyyMMdd-HHmmss",Locale.ROOT).format(new Date())+"-"+UUID.randomUUID().toString().substring(0,8)+".leo-backup.json");if(f.exists())throw new IOException("Numele există");write(f,archive(data));return f;}
 static void apply(Context c,JSONObject data)throws Exception{JSONObject groups=data.getJSONObject("preferences");for(String group:GROUPS){if(!groups.has(group))continue;SharedPreferences p=c.getSharedPreferences(group,0);SharedPreferences.Editor e=p.edit();for(Map.Entry<String,?> old:p.getAll().entrySet())if(allowed(group,old.getKey(),type(old.getValue())))e.remove(old.getKey());JSONObject values=groups.getJSONObject(group);for(Iterator<String> i=values.keys();i.hasNext();){String key=i.next();JSONObject row=values.getJSONObject(key);String t=row.getString("type");if(t.equals("set")){HashSet<String> valuesSet=new HashSet<String>();JSONArray arr=row.getJSONArray("value");for(int n=0;n<arr.length();n++)valuesSet.add(arr.getString(n));e.putStringSet(key,valuesSet);}else if(t.equals("int"))e.putInt(key,row.getInt("value"));else if(t.equals("boolean"))e.putBoolean(key,row.getBoolean("value"));else e.putString(key,row.getString("value"));}if(!e.commit())throw new IOException("Preferințe nesalvate");}File notes=new File(c.getFilesDir(),"notes.json");if(data.isNull("notes"))new AtomicFile(notes).delete();else write(notes,data.getJSONArray("notes").toString().getBytes(StandardCharsets.UTF_8));File wallpaper=Appearance.wallpaper(c);if(data.isNull("wallpaper"))new AtomicFile(wallpaper).delete();else write(wallpaper,Base64.decode(data.getString("wallpaper"),Base64.DEFAULT));JSONObject keys=data.getJSONObject("keyboard");for(String key:SECURE)if(!Settings.Secure.putString(c.getContentResolver(),key,keys.isNull(key)?null:keys.getString(key)))throw new IOException("Setare tastatură nesalvată");dictionary(c,"restore",data.getJSONObject("dictionary"));if(data.has("calendar"))CalendarArchive.apply(c,data.getJSONArray("calendar"));}
 static File pending(Context c){return new File(c.getFilesDir(),"backup-restore-pending.json");}
 static void recover(Context c)throws Exception{File journal=pending(c);if(atomicExists(journal)){JSONObject original=read(c,journal);apply(c,original);new AtomicFile(journal).delete();}}
 static final String[] CATEGORIES={"appearance","favorites","notes","keyboard","calendar"};
 static String category(String group){return group.equals("appearance")||group.equals("files-ui")?"appearance":group.equals("notes-draft")?"notes":group.equals("clock")?"appearance":"favorites";}
 static JSONObject selected(JSONObject incoming,JSONObject current,Set<String> chosen)throws Exception{JSONObject result=new JSONObject(current.toString());JSONObject target=result.getJSONObject("preferences"),source=incoming.getJSONObject("preferences");for(String group:GROUPS)if(chosen.contains(category(group))&&source.has(group))target.put(group,source.getJSONObject(group));if(chosen.contains("notes"))result.put("notes",incoming.get("notes"));if(chosen.contains("appearance"))result.put("wallpaper",incoming.get("wallpaper"));if(chosen.contains("keyboard")){result.put("keyboard",incoming.get("keyboard"));result.put("dictionary",incoming.get("dictionary"));}if(chosen.contains("calendar")&&incoming.has("calendar"))result.put("calendar",incoming.get("calendar"));else result.remove("calendar");return result;}
 static File restore(Context c,JSONObject data,Set<String> chosen)throws Exception{if(chosen.isEmpty())throw new IOException("Alege cel puțin o categorie");validate(c,data);JSONObject current=snapshot(c);JSONObject selection=selected(data,current,chosen);return restore(c,selection);}
 static File restore(Context c,JSONObject data)throws Exception{validate(c,data);JSONObject original=snapshot(c);if(!data.has("calendar"))original.remove("calendar");validate(c,original);File safety=export(c,new File(c.getFilesDir(),"documents/Backup-rollback"));write(pending(c),archive(original));try{apply(c,data);new AtomicFile(pending(c)).delete();return safety;}catch(Exception e){try{apply(c,original);new AtomicFile(pending(c)).delete();}catch(Exception rollback){throw new IOException("Restaurare incompletă; copie locală păstrată",rollback);}throw e;}}
}
